"""テストで、関数 `issue_practice.gh.run` を差し替える、状態を持つ偽の GitHub。

偽の `gh` (ファイル `issue-practice/tests/fake-gh`) は応答を前もって決めておく形なので、書き込みの後の状態を再度読み込む
手順 (途中で失敗させてから、同じ計画案でやり直す) を表しにくい。この偽物は、Issue・ラベル・マイルストーン・コメントを
メモリに持ち、リリースの書き込み (モジュール `issue_practice.releaseops` と `issue_practice.closecheck`) が使う `gh` の
コマンドだけを解釈する。知らないコマンドは、例外 `AssertionError` で知らせる (指定の漏れを、成功した応答と取り違えないため)。

失敗させるときは、`fail_when` に、引数の配列を受け取って真を返す関数を入れる。真を返した呼び出しを 1 回だけ失敗させる。
"""

import json
import re

LOGIN = "akm"


def _result(args, stdout="", exit_code=0, stderr=""):
    parsed = None
    if stdout.strip():
        try:
            parsed = json.loads(stdout)
        except ValueError:
            parsed = None
    return {"args": list(args), "exit_code": exit_code, "stdout": stdout, "stderr_tail": stderr, "timed_out": False,
            "failure": None if exit_code == 0 else "other", "json": parsed, "json_error": None}


class FakeGitHub:

    def __init__(self, repo="o/r"):
        self.repo = repo
        self.issues = {}  # 番号 -> 辞書
        self.milestones = {}  # 番号 -> 辞書
        self.labels = {}  # 名前 -> 辞書
        self.comments = {}  # Issue の番号 -> コメントの配列
        self.prs = {}  # 番号 -> 辞書
        self.next_number = 1
        self.next_milestone = 1
        self.next_comment = 1
        self.clock = 0
        self.calls = []
        self.fail_when = None

    # --- 状態を作る ---------------------------------------------------------------------------------------------

    def url(self, number, kind="issues"):
        return f"https://github.com/{self.repo}/{kind}/{number}"

    def _time(self):
        self.clock += 1
        return f"2026-11-14T00:{self.clock // 60:02d}:{self.clock % 60:02d}Z"

    def add_issue(self, title, body="", labels=(), milestone=None, state="OPEN", number=None):
        number = number or self.next_number
        self.next_number = max(self.next_number, number + 1)
        self.issues[number] = {"number": number, "title": title, "body": body, "labels": list(labels),
                               "milestone": milestone, "state": state, "created_at": self._time(), "blocked_by": [],
                               "blocking": [], "state_reason": None}
        self.comments.setdefault(number, [])
        return number

    def add_pr(self, number=None, state="MERGED", base="main", body=""):
        number = number or self.next_number
        self.next_number = max(self.next_number, number + 1)
        self.prs[number] = {"number": number, "state": state, "base": base, "body": body}
        return number

    def add_label(self, name):
        self.labels[name] = {"name": name, "color": "ededed", "description": ""}

    def add_milestone(self, title, description="", state="open"):
        number = self.next_milestone
        self.next_milestone += 1
        self.milestones[number] = {"number": number, "title": title, "description": description, "state": state,
                                   "html_url": f"https://github.com/{self.repo}/milestone/{number}"}
        return number

    def add_comment(self, number, body, login=LOGIN):
        comment_id = self.next_comment
        self.next_comment += 1
        self.comments.setdefault(number, []).append({
            "id": comment_id, "html_url": f"{self.url(number)}#issuecomment-{comment_id}", "body": body,
            "created_at": self._time(), "updated_at": "x", "user": {"login": login}})
        return f"{self.url(number)}#issuecomment-{comment_id}"

    # --- 読む -------------------------------------------------------------------------------------------------

    def _milestone_of(self, title):
        return next((m for m in self.milestones.values() if m["title"] == title), None)

    def _issue_json(self, number):
        if number in self.prs:
            pr = self.prs[number]
            return {"number": number, "url": self.url(number, "pull"), "state": pr["state"], "title": "PR", "body": pr["body"]}
        issue = self.issues[number]
        milestone = self.milestones.get(issue["milestone"]) if issue["milestone"] else None
        return {"number": number, "url": self.url(number), "state": issue["state"], "title": issue["title"],
                "body": issue["body"], "updatedAt": "x", "createdAt": issue["created_at"],
                "milestone": {"number": milestone["number"], "title": milestone["title"], "description": milestone["description"],
                              "dueOn": None} if milestone else None,
                "labels": [{"name": name} for name in issue["labels"]],
                "blockedBy": {"nodes": [self._node(n) for n in issue["blocked_by"]]},
                "blocking": {"nodes": [self._node(n) for n in issue["blocking"]]}, "parent": None}

    def _node(self, number):
        issue = self.issues[number]
        return {"number": number, "url": self.url(number), "title": issue["title"], "state": issue["state"]}

    def _rest_issue(self, number):
        issue = self.issues[number]
        milestone = self.milestones.get(issue["milestone"]) if issue["milestone"] else None
        return {"html_url": self.url(number), "number": number, "title": issue["title"], "state": issue["state"].lower(),
                "body": issue["body"], "created_at": issue["created_at"], "user": {"login": LOGIN},
                "labels": [{"name": name} for name in issue["labels"]],
                "milestone": {"number": milestone["number"], "title": milestone["title"]} if milestone else None}

    def _number(self, text):
        m = re.search(r"/(?:issues|pull)/([0-9]+)$", text)
        return int(m.group(1)) if m else int(text)

    # --- gh の実行 --------------------------------------------------------------------------------------------

    def run(self, args, timeout=None, mutation=False, expect_json=False, stdin=None):
        args = list(args)
        self.calls.append({"args": args, "stdin": stdin})
        if self.fail_when is not None and self.fail_when(args):
            self.fail_when = None
            return _result(args, exit_code=1, stderr="HTTP 502: Bad Gateway")
        return self._dispatch(args, stdin)

    def _dispatch(self, args, stdin):
        out = lambda value: _result(args, json.dumps(value, ensure_ascii=False))  # noqa: E731
        if args[:2] == ["api", "user"]:
            return out({"login": LOGIN})
        if args[:2] == ["label", "list"]:
            return out([{"name": name} for name in self.labels])
        if args[:2] == ["label", "create"]:
            self.add_label(args[2])
            return _result(args)
        if args[0] == "api":
            return self._api(args, out)
        if args[:2] == ["issue", "list"]:
            labels = [args[i + 1] for i, a in enumerate(args) if a == "--label"]
            found = [self._issue_json(n) for n, i in sorted(self.issues.items())
                     if i["state"] == "OPEN" and all(label in i["labels"] for label in labels)]
            return out(found)
        if args[:2] == ["issue", "view"] or args[:2] == ["pr", "view"]:
            number = self._number(args[2])
            if args[0] == "pr":
                pr = self.prs[number]
                return out({"number": number, "url": self.url(number, "pull"), "state": pr["state"],
                            "mergedAt": "x" if pr["state"] == "MERGED" else None, "baseRefName": pr["base"],
                            "isDraft": False, "body": pr["body"]})
            return out(self._issue_json(number))
        if args[:2] == ["issue", "create"]:
            title = args[args.index("--title") + 1]
            labels = [args[i + 1] for i, a in enumerate(args) if a == "--label"]
            missing = [label for label in labels if label not in self.labels]
            if missing:
                return _result(args, exit_code=1, stderr=f"could not add label: '{missing[0]}' not found")
            number = self.add_issue(title, body=stdin or "", labels=labels)
            return _result(args, self.url(number) + "\n")
        if args[:2] == ["issue", "edit"]:
            return self._edit(args, stdin)
        if args[:2] == ["issue", "comment"]:
            return _result(args, self.add_comment(self._number(args[2]), stdin or "") + "\n")
        if args[:2] == ["issue", "close"]:
            issue = self.issues[self._number(args[2])]
            issue["state"] = "CLOSED"
            issue["state_reason"] = args[args.index("--reason") + 1] if "--reason" in args else "completed"
            return _result(args)
        raise AssertionError(f"偽の GitHub が知らないコマンド: {args!r}")

    def _edit(self, args, stdin):
        issue = self.issues[self._number(args[2])]
        i = 3
        while i < len(args):
            flag = args[i]
            if flag == "--title":
                issue["title"] = args[i + 1]
            elif flag == "--body-file":
                issue["body"] = stdin or ""
            elif flag == "--milestone":
                milestone = self._milestone_of(args[i + 1])
                if milestone is None or milestone["state"] != "open":
                    return _result(args, exit_code=1, stderr=f"could not add to milestone '{args[i + 1]}': not found")
                issue["milestone"] = milestone["number"]
            elif flag == "--remove-milestone":
                issue["milestone"] = None
                i += 1
                continue
            elif flag == "--add-label":
                if args[i + 1] not in self.labels:
                    return _result(args, exit_code=1, stderr=f"'{args[i + 1]}' not found")
                if args[i + 1] not in issue["labels"]:
                    issue["labels"].append(args[i + 1])
            elif flag == "--remove-label":
                if args[i + 1] in issue["labels"]:
                    issue["labels"].remove(args[i + 1])
            else:
                raise AssertionError(f"偽の GitHub が知らない issue edit のフラグ: {flag}")
            i += 2
        return _result(args)

    def _api(self, args, out):
        path = args[1]
        prefix = f"repos/{self.repo}/"
        assert path.startswith(prefix), path
        path = path[len(prefix):]
        fields = {args[i + 1].split("=", 1)[0]: args[i + 1].split("=", 1)[1] for i, a in enumerate(args) if a == "-f"}
        method = args[args.index("-X") + 1] if "-X" in args else "GET"
        m = re.match(r"^milestones\?state=(open|all)&per_page=100$", path)
        if m:
            found = [ms for _, ms in sorted(self.milestones.items()) if m.group(1) == "all" or ms["state"] == "open"]
            return out([found])
        if path == "milestones" and method == "POST":
            if self._milestone_of(fields["title"]):
                return _result(args, exit_code=1, stderr="HTTP 422: Validation Failed (already_exists)")
            number = self.add_milestone(fields["title"], fields.get("description", ""))
            return out(self.milestones[number])
        m = re.match(r"^milestones/([0-9]+)$", path)
        if m and method == "PATCH":
            milestone = self.milestones[int(m.group(1))]
            milestone.update(fields)
            return out(milestone)
        if path == "issues?state=open&per_page=100":
            return out([[self._rest_issue(n) for n, i in sorted(self.issues.items()) if i["state"] == "OPEN"]])
        m = re.match(r"^issues\?milestone=([0-9]+)&state=all&per_page=100$", path)
        if m:
            return out([[self._rest_issue(n) for n, i in sorted(self.issues.items()) if i["milestone"] == int(m.group(1))]])
        m = re.match(r"^issues/([0-9]+)/comments$", path)
        if m:
            return out([list(self.comments.get(int(m.group(1)), []))])
        raise AssertionError(f"偽の GitHub が知らない API: {args!r}")
"""テストで偽の `gh` (ファイル `issue-practice/tests/fake-gh`) を使うための基底クラス。

PATH の先頭に偽の `gh` のディレクトリを加え、環境変数で振る舞いを決める。実物の `gh` は使わない。
プラグイン issue-dispatch のファイル `issue-dispatch/tests/test_project.py` のクラス `FakeGhCase` と同じ形。
"""

import json
import os
import subprocess
import sys
import tempfile
import unittest

HERE = os.path.dirname(os.path.abspath(__file__))
SCRIPTS = os.path.join(HERE, "..", "scripts")
ENTRY = os.path.join(SCRIPTS, "issue_practice.py")
FAKE = os.path.join(HERE, "fake-gh")
FIXTURES = os.path.join(HERE, "fixtures", "gh")

if SCRIPTS not in sys.path:
    sys.path.insert(0, SCRIPTS)

_ENV_KEYS = ("PATH", "FAKE_GH_ARGS", "FAKE_GH_RESPONSES", "FAKE_GH_MODE", "FAKE_GH_SLEEP", "FAKE_GH_EXIT")


def fixture(name, kind="stdout"):
    with open(os.path.join(FIXTURES, f"{name}.{kind}"), encoding="utf-8") as f:
        return f.read()


def fixture_json(name):
    return json.loads(fixture(name))


class FakeGhCase(unittest.TestCase):

    def setUp(self):
        self._tmp = tempfile.TemporaryDirectory()
        self.root = self._tmp.name
        self.bin = os.path.join(self.root, "bin")
        os.makedirs(self.bin)
        os.symlink(FAKE, os.path.join(self.bin, "gh"))
        self.args_file = os.path.join(self.root, "args.jsonl")
        self.responses_file = os.path.join(self.root, "responses.json")
        self._saved = {k: os.environ.get(k) for k in _ENV_KEYS}
        os.environ["PATH"] = self.bin + os.pathsep + os.environ.get("PATH", "")
        os.environ["FAKE_GH_ARGS"] = self.args_file
        os.environ["FAKE_GH_RESPONSES"] = self.responses_file
        for k in ("FAKE_GH_MODE", "FAKE_GH_SLEEP", "FAKE_GH_EXIT"):
            os.environ.pop(k, None)
        self.responses([])

    def tearDown(self):
        for k, v in self._saved.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
        self._tmp.cleanup()

    def responses(self, entries):
        with open(self.responses_file, "w", encoding="utf-8") as f:
            json.dump(entries, f, ensure_ascii=False)

    def recorded_full(self):
        if not os.path.exists(self.args_file):
            return []
        with open(self.args_file, encoding="utf-8") as f:
            return [json.loads(line) for line in f if line.strip()]

    def recorded(self):
        return [r["args"] for r in self.recorded_full()]

    def cli(self, *args, stdin=None):
        """CLI の入口をサブプロセスで実行する。返り値は (終了コード, 標準出力を JSON として読んだ値か None, 標準エラー出力)。"""
        completed = subprocess.run([sys.executable, ENTRY, *args], capture_output=True, text=True, input=stdin,
                                   env=dict(os.environ))
        try:
            payload = json.loads(completed.stdout) if completed.stdout.strip() else None
        except ValueError:
            payload = None
        return completed.returncode, payload, completed.stderr
#!/usr/bin/env python3
"""リリース計画の計画案を GitHub に書く「示す」(release plan) と「実行する」(release apply) のテスト
(計画の U4・R38・R39・R40・KTD3・KTD5)。

状態を持つ偽の GitHub (ファイル `issue-practice/tests/fakegithub.py`) で、関数 `gh.run` を差し替える。途中で失敗させてから
同じ計画案でやり直し、済んでいない書き込みだけを行うことを確認する。
"""

import datetime
import os
import re
import tempfile
import unittest
from unittest import mock

from fakegh_case import HERE, FakeGhCase
from fakegithub import FakeGitHub

from issue_practice import bodies, gh, releaseops, releaseplan  # noqa: E402

REPO = "o/r"
NAME = "20261114-1200-release-plan-next.md"
NAME2 = "20261115-1200-release-plan-next.md"


def draft_text(rows, dests="なし", cancels="なし", kind="新しい計画", current=None, target="なし"):
    """rows は (#番号 かキー, 主題) の配列。current は (URL, 本文) か None。"""
    sources = f"- {current[0]} 本文の SHA-256: {bodies.body_sha256(current[1])}" if current else "- なし"
    table = "\n".join(f"| {i} | {ref} | {subject} |" for i, (ref, subject) in enumerate(rows, start=1))
    return (f"# 計画案: 次のリリース\n\n## 元にした Issue\n\n{sources}\n\n"
            f"## 対象\n\n- 種類: {kind}\n- リリース対象: {target}\n- 今の計画: {current[0] if current else 'なし'}\n\n"
            f"## リリースの順番\n\n| 順 | リリース Issue | 主題 |\n| --- | --- | --- |\n{table}\n\n"
            f"## Issue の入れ先\n\n{dests}\n\n## 取りやめるリリース\n\n{cancels}\n")


def dest_table(*pairs):
    return "| Issue | 入れるリリース |\n| --- | --- |\n" + "\n".join(f"| {a} | {b} |" for a, b in pairs)


def cancel_table(*rows):
    return "| リリース Issue | 理由 | メモの移し先 |\n| --- | --- | --- |\n" + "\n".join(f"| {a} | {b} | {c} |" for a, b, c in rows)


class ParseTest(unittest.TestCase):

    def parse(self, text, name=NAME):
        return releaseops.parse_plan(text, name, REPO)

    def test_reads_draft(self):
        parsed = self.parse(draft_text([("#3", "既存"), ("a", "新しい")], dests=dest_table(("#5", "a"), ("#6", "未定"))))
        self.assertEqual(parsed["errors"], [])
        self.assertEqual(parsed["kind"], "新しい計画")
        self.assertEqual([(r["number"], r["key"]) for r in parsed["rows"]], [(3, None), (None, "a")])
        self.assertEqual([(d["number"], d["value"]) for d in parsed["dests"]], [(5, "a"), (6, "未定")])

    def test_errors(self):
        url = "https://github.com/o/r/issues/30"
        cases = {
            "知らない種類": draft_text([("a", "x")], kind="大きな計画"),
            "入れ先が表に無い": draft_text([("a", "x")], dests=dest_table(("#5", "b"))),
            "入れ先がリリース Issue": draft_text([("#3", "x")], dests=dest_table(("#3", "#3"))),
            "キー plan": draft_text([("plan", "x")]),
            "急ぎで今の計画が無い": draft_text([("a", "x")], kind="急ぎのリリースの追加"),
            "急ぎで取りやめる": draft_text([("#3", "x"), ("a", "y")], kind="急ぎのリリースの追加", current=(url, "b"),
                                    cancels=cancel_table(("#4", "理由", "なし"))),
            "急ぎでキーが無い": draft_text([("#3", "x")], kind="急ぎのリリースの追加", current=(url, "b")),
            "取りやめるのが表にもある": draft_text([("#3", "x")], cancels=cancel_table(("#3", "理由", "なし"))),
            "今の計画が元にした Issue に無い": draft_text([("a", "x")]).replace("- 今の計画: なし", f"- 今の計画: {url}"),
            "節の順序": draft_text([("a", "x")]).replace("## Issue の入れ先", "## 入れ先"),
        }
        for name, text in cases.items():
            with self.subTest(name):
                self.assertTrue(self.parse(text)["errors"], name)


class ReleaseOpsCase(unittest.TestCase):

    def setUp(self):
        self.gh = FakeGitHub(REPO)
        patcher = mock.patch.object(gh, "run", self.gh.run)
        patcher.start()
        self.addCleanup(patcher.stop)
        patcher = mock.patch.object(releaseops, "today", lambda: datetime.date(2026, 11, 14))
        patcher.start()
        self.addCleanup(patcher.stop)
        self._tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self._tmp.cleanup)

    def write_draft(self, text, name=NAME):
        path = os.path.join(self._tmp.name, name)
        with open(path, "w", encoding="utf-8") as f:
            f.write(text)
        return path

    def writes(self):
        reads = (["api", "user"], ["label", "list"], ["issue", "list"], ["issue", "view"], ["pr", "view"])
        return [c for c in self.gh.calls if c["args"][:2] not in reads
                and not (c["args"][0] == "api" and "-X" not in c["args"])]

    def find(self, pattern):
        return [n for n, i in self.gh.issues.items() if re.search(pattern, i["title"])]

    def released(self, subject, done=False):
        """主題 subject のリリース Issue とマイルストーンを、前もって作っておく。"""
        number = self.gh.add_issue("仮")
        self.gh.issues[number]["title"] = releaseplan.release_title(number, subject, draft=not done)
        milestone = self.gh.add_milestone(releaseplan.milestone_title(number, subject), f"リリース Issue: {self.gh.url(number)}")
        self.gh.issues[number]["body"] = f"## 参照\n\n- リリースマイルストーン: {self.gh.milestones[milestone]['html_url']}\n"
        return number, milestone

    def current_plan(self, rows, date="20261101"):
        body = "## リリースの順番\n\n" + releaseplan.render_table([{"number": n, "subject": s} for n, s in rows]) + "\n"
        self.gh.add_label("current")
        number = self.gh.add_issue(releaseplan.plan_title(date), body=body, labels=["current"])
        return number, body


class FirstPlanTest(ReleaseOpsCase):

    def setUp(self):
        super().setUp()
        self.gh.add_issue("要望 1")  # #1
        self.gh.add_issue("要望 2")  # #2
        self.path = self.write_draft(draft_text([("a", "バックアップ"), ("b", "絞り込み")],
                                                dests=dest_table(("#1", "a"), ("#2", "b"))))

    def test_plan_shows_steps_without_writing(self):
        result = releaseops.plan(self.path, REPO)
        self.assertEqual(result["status"], "ok", result["errors"])
        self.assertEqual(self.writes(), [], "示すときは書き込まない")
        self.assertEqual([l["name"] for l in result["labels_to_create"]], ["current"])
        self.assertEqual([(a["step"], a["action"]) for a in result["actions"]], [
            (0, "create-label"), (1, "create-plan"), (1, "record-approval"),
            (2, "create-release"), (2, "set-release-number"), (2, "create-milestone"), (2, "write-release-body"),
            (2, "create-release"), (2, "set-release-number"), (2, "create-milestone"), (2, "write-release-body"),
            (2, "set-milestone"), (2, "set-milestone"), (2, "write-plan-table"), (3, "add-current"),
            (5, "record-current-swap")], "古い計画が無いので、手順 4 と 6 は行わない")

    def test_apply_writes_first_plan(self):
        result = releaseops.apply(self.path, REPO)
        self.assertEqual(result["status"], "ok", result["errors"])
        plan = self.find("^📅 リリース計画 20261114$")
        self.assertEqual(len(plan), 1)
        plan = self.gh.issues[plan[0]]
        self.assertEqual(plan["labels"], ["current"])
        releases = self.find("🔖 リリース")
        self.assertEqual([self.gh.issues[n]["title"] for n in releases],
                         [f"[DRAFT] 🔖 リリース R{releases[0]} (バックアップ)", f"[DRAFT] 🔖 リリース R{releases[1]} (絞り込み)"],
                         "題名に番号を書き足す")
        for number in releases:
            milestone = next(m for m in self.gh.milestones.values() if m["title"].startswith(f"R{number} "))
            self.assertIn(self.gh.url(number), milestone["description"], "マイルストーンの説明にリリース Issue の URL")
